template:
fn update_if_pos(ptr: *mut i32) -> bool {
    if ptr.is_null() {
        return false;
    }
    unsafe {
        if ⟦slot1⟧ > 0 {
            ⟦slot2⟧ = 42;
            true
        } else {
            false
        }
    }
}

fn main() {
    let mut x = 10;
    update_if_pos(&mut x as *mut i32);
}

tests:
#[test]
fn updates_positive() {
    let mut x = 10;
    assert!(update_if_pos(&mut x as *mut i32));
    assert_eq!(x, 42);
}

#[test]
fn ignores_negative() {
    let mut x = -5;
    assert!(!update_if_pos(&mut x as *mut i32));
    assert_eq!(x, -5);
}
